//! Ranks code blocks by BM25 relevance, boosted by symbol kind, by query terms in the declared name and by how many
//! matched lines each block covers.

mod bm25;
mod boost;
mod tokenize_doc;

use std::cmp::Ordering;
use std::collections::HashMap;
use std::hash::BuildHasher;

pub use bm25::{round6, score};
pub use boost::{coverage_boost, name_match_boost, node_type_boost};
pub use tokenize_doc::tokenize_block;

use crate::types::{CodeBlock, RankedBlock, SymbolKind};

/// Scores each block against `query_terms` and returns them best first, with 1-based ranks.
///
/// Each block comes with its document tokens, usually from [`tokenize_block`]. The corpus for BM25 is `blocks`
/// itself: its size and average token count feed [`score`], and `df` gives each term's document frequency. A block's
/// `final_score` is `round6(bm25 * node_type_boost + coverage_boost)`, and its `parent` becomes the ranked block's
/// `parent_context`.
///
/// The order is `final_score` descending (with `-0.0` equal to `0.0`), then ascending `file` by path components,
/// `line_start`, `line_end`, `node_kind` in `SymbolKind` declaration order, and `code` by bytes. Reordering the input
/// never reorders the output, except that blocks equal on all six keys keep their relative input order.
///
/// # Examples
///
/// ```
/// use std::collections::HashMap;
///
/// use camino::Utf8PathBuf;
/// use monokl::rank::{rank_blocks, tokenize_block};
/// use monokl::types::{CodeBlock, SymbolKind};
///
/// let block = |file: &str, code: &str| CodeBlock {
///     file: Utf8PathBuf::from(file),
///     line_start: 1,
///     line_end: 1,
///     node_kind: SymbolKind::Function,
///     code: code.to_string(),
///     symbol_signature: None,
///     matched_lines: Vec::new(),
///     matched_keywords: Vec::new(),
///     parent: None,
/// };
/// let blocks: Vec<_> = [block("b.ts", "parseConfig()"), block("a.ts", "readFile()")]
///     .into_iter()
///     .map(|b| {
///         let tokens = tokenize_block(&b);
///         (b, tokens)
///     })
///     .collect();
/// let df = HashMap::from([("config".to_string(), 1)]);
///
/// let ranked = rank_blocks(blocks, &["config"], &df);
/// assert_eq!(ranked[0].block.file, "b.ts");
/// assert_eq!(ranked[0].rank, 1);
/// assert_eq!(ranked[1].final_score, 0.0);
/// ```
pub fn rank_blocks<S: BuildHasher>(
    blocks: Vec<(CodeBlock, Vec<String>)>,
    query_terms: &[&str],
    df: &HashMap<String, usize, S>,
) -> Vec<RankedBlock> {
    if blocks.is_empty() {
        return Vec::new();
    }
    let corpus_size = blocks.len();
    let total_tokens: usize = blocks.iter().map(|(_, tokens)| tokens.len()).sum();
    let avg_doc_len = bm25::as_f64(total_tokens) / bm25::as_f64(corpus_size);
    let mut ranked: Vec<RankedBlock> = blocks
        .into_iter()
        .map(|(block, doc_tokens)| {
            let bm25_score = score(&doc_tokens, query_terms, avg_doc_len, corpus_size, df);
            let coverage_boost = coverage_boost(&block);
            let node_type_boost = node_type_boost(block.node_kind);
            let name_boost = name_match_boost(&block, query_terms);
            let parent_context = block.parent.clone();
            RankedBlock {
                block,
                bm25_score,
                coverage_boost,
                node_type_boost,
                final_score: round6(bm25_score * name_boost * node_type_boost + coverage_boost),
                rank: 0,
                parent_context,
            }
        })
        .collect();
    ranked.sort_by(best_first);
    for (rank, block) in (1..).zip(&mut ranked) {
        block.rank = rank;
    }
    ranked
}

/// Orders ranked blocks best first by a total order over everything that tells two blocks apart: `final_score`
/// descending, then `file` (component-wise), `line_start`, `line_end`, `node_kind` and `code` ascending.
///
/// `-0.0` and `0.0` compare equal so the sign of a zero score cannot reorder blocks; every other score, NaN included,
/// follows [`f64::total_cmp`].
fn best_first(a: &RankedBlock, b: &RankedBlock) -> Ordering {
    score_order(b.final_score)
        .total_cmp(&score_order(a.final_score))
        .then_with(|| a.block.file.cmp(&b.block.file))
        .then_with(|| a.block.line_start.cmp(&b.block.line_start))
        .then_with(|| a.block.line_end.cmp(&b.block.line_end))
        .then_with(|| kind_order(a.block.node_kind).cmp(&kind_order(b.block.node_kind)))
        .then_with(|| a.block.code.cmp(&b.block.code))
}

/// Maps `-0.0` to `0.0`, which [`f64::total_cmp`] would otherwise order below it.
fn score_order(score: f64) -> f64 {
    if score == 0.0 { 0.0 } else { score }
}

/// Returns the position of `kind` in `SymbolKind`'s declaration order.
fn kind_order(kind: SymbolKind) -> u8 {
    match kind {
        SymbolKind::Function => 0,
        SymbolKind::Method => 1,
        SymbolKind::Constructor => 2,
        SymbolKind::Class => 3,
        SymbolKind::Struct => 4,
        SymbolKind::Enum => 5,
        SymbolKind::Interface => 6,
        SymbolKind::TypeAlias => 7,
        SymbolKind::Property => 8,
        SymbolKind::Field => 9,
        SymbolKind::Variable => 10,
        SymbolKind::Module => 11,
        SymbolKind::Impl => 12,
        SymbolKind::Macro => 13,
        SymbolKind::Other => 14,
    }
}

use std::collections::HashMap;
use std::hash::BuildHasher;

const K1: f64 = 1.5;
const B: f64 = 0.5;
const DP: f64 = 1_000_000.0;

/// Rounds `x` to 6 decimal places, halves away from zero.
///
/// Every score is rounded so output is stable across platforms and readable in agent-facing text.
///
/// # Examples
///
/// ```
/// use monokl::rank::round6;
///
/// assert_eq!(round6(0.1234565), 0.123457);
/// assert_eq!(round6(1.0000004), 1.0);
/// ```
pub fn round6(x: f64) -> f64 {
    (x * DP).round() / DP
}

/// Returns the Okapi BM25 score of one document for `query_terms`, rounded with [`round6`].
///
/// Uses `K1 = 1.5` and `B = 0.5`. `corpus_size` is the number of documents and `df` maps a term to the number of
/// documents containing it; a term missing from `df` has a document frequency of 0. A query term absent from the
/// document contributes nothing. Term frequency is exact, case-sensitive token equality, and a term repeated in
/// `query_terms` counts once per occurrence. Returns 0.0 when either `doc_tokens` or `query_terms` is empty, or when
/// `avg_doc_len` is not a finite number above zero.
///
/// # Examples
///
/// ```
/// use std::collections::HashMap;
///
/// use monokl::rank::score;
///
/// let doc: Vec<String> = ["foo", "foo", "bar", "baz"].map(String::from).into();
/// let df = HashMap::from([("foo".to_string(), 1)]);
/// assert_eq!(score(&doc, &["foo"], 4.0, 2, &df), 0.99021);
/// ```
pub fn score<S: BuildHasher>(
    doc_tokens: &[String],
    query_terms: &[&str],
    avg_doc_len: f64,
    corpus_size: usize,
    df: &HashMap<String, usize, S>,
) -> f64 {
    // A non-positive or non-finite average length has no meaning as a corpus statistic and would turn the length
    // normalization into a sign flip or NaN.
    if query_terms.is_empty() || doc_tokens.is_empty() || !(avg_doc_len.is_finite() && avg_doc_len > 0.0) {
        return 0.0;
    }
    let doc_len = as_f64(doc_tokens.len());
    let n = as_f64(corpus_size);
    let mut total = 0.0;
    for term in query_terms {
        let tf = doc_tokens.iter().filter(|token| token == term).count();
        if tf == 0 {
            continue;
        }
        let tf = as_f64(tf);
        let df_t = as_f64(df.get(*term).copied().unwrap_or(0));
        let idf = ((n - df_t + 0.5) / (df_t + 0.5) + 1.0).ln();
        let norm_factor = K1 * (1.0 - B + B * (doc_len / avg_doc_len));
        total += idf * ((tf * (K1 + 1.0)) / (tf + norm_factor));
    }
    round6(total)
}

/// Converts a count to `f64`.
#[expect(clippy::cast_precision_loss, reason = "token and document counts stay far below 2^53")]
pub(super) fn as_f64(count: usize) -> f64 {
    count as f64
}

#[cfg(test)]
use super::bm25::{as_f64, round6};
use crate::tokens::tokenize_source;
use crate::types::{CodeBlock, SymbolKind};

/// Returns the fraction of the block's matched lines that fall inside `line_start..=line_end`, rounded with
/// [`round6`].
///
/// Returns 0.0 when `matched_lines` is empty. A block whose `line_end` is before its `line_start` contains no lines.
///
/// # Examples
///
/// ```
/// use camino::Utf8PathBuf;
/// use monokl::rank::coverage_boost;
/// use monokl::types::{CodeBlock, SymbolKind};
///
/// let block = CodeBlock {
///     file: Utf8PathBuf::from("src/a.ts"),
///     line_start: 10,
///     line_end: 20,
///     node_kind: SymbolKind::Function,
///     code: String::new(),
///     symbol_signature: None,
///     matched_lines: vec![12, 30, 40],
///     matched_keywords: Vec::new(),
///     parent: None,
/// };
/// assert_eq!(coverage_boost(&block), 0.333333);
/// ```
pub fn coverage_boost(block: &CodeBlock) -> f64 {
    if block.matched_lines.is_empty() {
        return 0.0;
    }
    let lines = block.line_start..=block.line_end;
    let inside = block.matched_lines.iter().filter(|line| lines.contains(*line)).count();
    round6(as_f64(inside) / as_f64(block.matched_lines.len()))
}

/// Returns the multiplier for how many query terms the block's declared name contains, from 1.0 to 3.0.
///
/// The name is the head of the block: its signature, or without one its first line that is not a comment or a
/// decorator, cut at the first `(`, `<`, `{`, `=` or `:`. So parameters, return types and the body do not count. In a
/// Rust file the parentheses of a restricted visibility (`pub(crate)`) do not cut the head. The
/// head is tokenized like a document, and the multiplier is `round6(1 + 2 * matched / query_terms.len())`, where
/// `matched` counts the query terms, repeats included, that the head contains. Returns 1.0 when `query_terms` is empty.
///
/// A body can mention every query word without the block being about them; a name that holds them says what it is.
///
/// # Examples
///
/// ```
/// use camino::Utf8PathBuf;
/// use monokl::rank::name_match_boost;
/// use monokl::types::{CodeBlock, SymbolKind};
///
/// let block = CodeBlock {
///     file: Utf8PathBuf::from("src/a.ts"),
///     line_start: 1,
///     line_end: 3,
///     node_kind: SymbolKind::Function,
///     code: String::new(),
///     symbol_signature: Some("function mergeConfig(a: Config, b: Config)".to_string()),
///     matched_lines: Vec::new(),
///     matched_keywords: Vec::new(),
///     parent: None,
/// };
/// assert_eq!(name_match_boost(&block, &["merge", "config", "deep", "copy"]), 2.0);
/// ```
pub fn name_match_boost(block: &CodeBlock, query_terms: &[&str]) -> f64 {
    if query_terms.is_empty() {
        return 1.0;
    }
    let text = block.symbol_signature.as_deref().unwrap_or(&block.code);
    let line = text.lines().map(str::trim).find(|line| !is_comment_or_decorator(line)).unwrap_or_default();
    let name_tokens = if block.file.extension() == Some("rs") {
        tokenize_source(&unrestricted(line))
    } else {
        tokenize_source(head_of(line))
    };
    let matched = query_terms.iter().filter(|term| name_tokens.iter().any(|token| token == *term)).count();
    round6(1.0 + 2.0 * as_f64(matched) / as_f64(query_terms.len()))
}

fn head_of(line: &str) -> &str {
    line.split(['(', '<', '{', '=', ':']).next().unwrap_or_default()
}

/// The head of a Rust declaration line with a restricted visibility (`pub(crate)`, `pub(super)`, `pub(in path)`) read as
/// a plain `pub`, whose `(` would otherwise end the head before the name. The other modifiers (`async`, `const`,
/// `unsafe`, `extern "C"`, `default`) hold no cut character and stay in the head.
fn unrestricted(line: &str) -> String {
    let restriction = line
        .strip_prefix("pub")
        .map(str::trim_start)
        .filter(|rest| rest.starts_with('('))
        .and_then(|rest| rest.split_once(')'));
    match restriction {
        Some((_, rest)) => format!("pub {}", head_of(rest)),
        None => head_of(line).to_owned(),
    }
}

/// Whether a trimmed line carries no declaration: it is blank, a comment or comment continuation, or a decorator.
fn is_comment_or_decorator(line: &str) -> bool {
    line.is_empty()
        || line.starts_with("//")
        || line.starts_with("/*")
        || line.starts_with('*')
        || line.starts_with('@')
}

/// Returns the score multiplier for a block's symbol kind.
///
/// Callable units rank highest, then type definitions, then bindings; `Other` ranks lowest.
///
/// # Examples
///
/// ```
/// use monokl::rank::node_type_boost;
/// use monokl::types::SymbolKind;
///
/// assert_eq!(node_type_boost(SymbolKind::Function), 1.5);
/// assert_eq!(node_type_boost(SymbolKind::Other), 0.7);
/// ```
pub fn node_type_boost(kind: SymbolKind) -> f64 {
    match kind {
        SymbolKind::Function => 1.5,
        SymbolKind::Class | SymbolKind::Method | SymbolKind::Constructor => 1.4,
        SymbolKind::Interface | SymbolKind::Struct => 1.3,
        SymbolKind::TypeAlias | SymbolKind::Enum => 1.2,
        SymbolKind::Variable | SymbolKind::Impl => 1.1,
        SymbolKind::Property | SymbolKind::Field | SymbolKind::Macro => 1.0,
        SymbolKind::Module => 0.9,
        SymbolKind::Other => 0.7,
    }
}

